insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('visual-ai-builders-fundamentals','visual-ai-builders-fundamentals','בניית AI חזותית — יסודות ובחירת כלי','concept','עורך חזותי מחבר מודלים, ידע וכלים לתהליך. לומדים להפריד מצב וחוזי נתונים, הרשאות ובדיקות מהתצוגה, ולהחליט מתי פלטפורמה מוסיפה ערך ומתי שירות קוד קטן מספיק.','published','verified','2026-11-03',1,'יישום visual06-20261103-v1 המאושר. דוגמאות ותרגילים מוצעים שלא הורצו; אין הבטחת ביצועים, אבטחה או שוויון SDK.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('langflow','langflow','Langflow','platform','פלטפורמה חזותית להרכבת יישומי AI, סוכנים ו־RAG מרכיבים שניתן להרחיב ב־Python ולהפעיל דרך API. מתאימה להבנת זרימת הנתונים והמעבר מהגרף לקוד, עם אחריות לבידוד ותפעול.','published','verified','2026-11-03',1,'יישום visual06-20261103-v1 המאושר. דוגמאות ותרגילים מוצעים שלא הורצו; אין הבטחת ביצועים, אבטחה או שוויון SDK.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('microsoft-copilot-studio','microsoft-copilot-studio','Microsoft Copilot Studio','platform','שירות SaaS חזותי של Microsoft לבנייה וניהול של סוכנים וזרימות המחוברים לנתוני ארגון ולערוצי עבודה. מתאים להיכרות עם סביבת Microsoft, תוך הבחנה בין רישיונות, harnesses וממשקי אינטגרציה.','published','verified','2026-11-03',1,'יישום visual06-20261103-v1 המאושר. דוגמאות ותרגילים מוצעים שלא הורצו; אין הבטחת ביצועים, אבטחה או שוויון SDK.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('sim','sim','Sim','platform','סביבת עבודה חזותית לסוכנים ולזרימות עם כלים, אירועים, ידע ופריסה דרך API או MCP. משלבת עריכה חזותית וקוד ואפשרויות cloud ו־self-host, עם אחריות לרישוי, נתונים ושירותי רקע.','published','verified','2026-11-03',1,'יישום visual06-20261103-v1 המאושר. דוגמאות ותרגילים מוצעים שלא הורצו; אין הבטחת ביצועים, אבטחה או שוויון SDK.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('botpress','botpress','Botpress','platform','פלטפורמת Cloud לבניית סוכני שיחה בעורך Studio, עם ידע, מצב, ערוצים והעברה לנציג. ניתן להרחיב בקוד TypeScript ולצרוך שירותים ב־HTTP, תוך הבחנה מהגרסאות ההיסטוריות להתקנה עצמית.','published','verified','2026-11-03',1,'יישום visual06-20261103-v1 המאושר. דוגמאות ותרגילים מוצעים שלא הורצו; אין הבטחת ביצועים, אבטחה או שוויון SDK.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('flowise','flowise','Flowise — היסטורי','platform','תיעוד היסטורי בלבד: Flowise הייתה סביבת הרכבה חזותית ליישומי AI. הפרויקט הגיע ל־EOL ב־31/08/2026 לאחר הקפאה וארכוב; אינו מומלץ לפיתוח חדש ואינו מופיע בקטלוג הפעיל.','archived','verified','2026-11-03',1,'תיעוד היסטורי מאושר בלבד; לא מומלץ לפיתוח חדש, מוסתר מהקטלוג הפעיל. תרחישי מעבר מוצעים ולא הורצו.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entries (id,slug,name,kind,summary,publication_status,verification_status,verified_at,revision,revision_note,added_at,added_at_basis,discovered_at,approved_at,approval_reference) values ('openai-agent-builder','openai-agent-builder','OpenAI Agent Builder — היסטורי','platform','תיעוד היסטורי בלבד: Agent Builder הוא canvas חזותי ש־OpenAI הוציאה משימוש. הסגירה מתוכננת ל־30/11/2026; אינו מומלץ לפיתוח חדש. ChatKit נשאר זמין ואינו מסומן כאן כמוצר שנסגר.','archived','verified','2026-11-03',1,'תיעוד היסטורי מאושר בלבד; לא מומלץ לפיתוח חדש, מוסתר מהקטלוג הפעיל. תרחישי מעבר מוצעים ולא הורצו.','2026-11-03','approved_proposal','2026-11-03','2026-11-03','User approved visual06-20261103-v1 V06-01–V06-07 and requested historical non-active Flowise/Agent Builder records; docs/DECISIONS.md D-035');
insert into academy.entry_categories (entry_id,category_id,position) values ('visual-ai-builders-fundamentals','06',0);
insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('visual-ai-builders-fundamentals','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: React שולח question ו־requestId ל־ASP.NET Core. השרת מזהה את המשתמש, בוחר מסמכים מורשים ומפעיל זרימה המחזירה answer, sourceIds ו־needsReview. פתיחת קריאת שירות היא פעולה נפרדת, לאחר אישור המשתמש ובדיקת הרשאות חוזרת בשרת; אין לתת למודל חיבור SQL חופשי.','שרטטו זרימת שאלת נוהל ופתיחת קריאה. הגדירו JSON לכל מעבר וחמש בדיקות: מקור חסר, הרשאה חסרה, timeout, כשל כלי וקלט המנסה לשנות הוראות. השוו למימוש endpoint יחיד ב־ASP.NET Core; אל תקימו כמה פלטפורמות לפני שיש צורך.','העקרונות מתאימים ל־C#/.NET, Python ו־TypeScript. שפת המימוש של העורך אינה שפת SDK; HTTP מאפשר אינטגרציה ואינו מבטיח שוויון יכולות.','Dify למעטפת יישום וידע; Langflow לרכיבי Python; Copilot Studio לסביבת Microsoft; Sim לזרימות סוכנים ואירועים; Botpress לשיחה. n8n הקיימת מתאימה גם לאוטומציות כלליות. בחרו כלי מעשי אחד, לא את כולם.');
insert into academy.entry_sections (entry_id,position,title,body) values ('visual-ai-builders-fundamentals',0,'גרף, מצב וחוזה נתונים','Node הוא שלב עם קלט ופלט, בדומה לפונקציה או endpoint. שמרו מצב שיחה בנפרד מתוצאה עסקית ונסחו schema מפורש. Retry צריך להיות מוגבל; פעולת כתיבה דורשת idempotency כדי שלא תבוצע פעמיים לאחר timeout. אלה עקרונות תכנון שלנו, לא יכולת מובטחת של כל עורך.');
insert into academy.entry_sections (entry_id,position,title,body) values ('visual-ai-builders-fundamentals',1,'זרימה דטרמיניסטית מול סוכן','Workflow מתאים לסדר צעדים וכללים ידועים; סוכן בוחר כלים לפי ההקשר ולכן דורש גבולות, תקציב ותצפית. אין צורך במספר סוכנים כדי לענות על שאלה ולשלוף מסמך. התחילו בזרימה הקטנה ביותר שמכסה את התרחיש.');
insert into academy.entry_sections (entry_id,position,title,body) values ('visual-ai-builders-fundamentals',2,'API, הרשאות ובדיקות','React פונה לשרת מאומת; מפתחות שירות נשארים בשרת. זהות שיחה אינה תחליף להרשאת משתמש. בדקו פלט מובנה, מקור תשובה וכשל שירות; Trace מסביר מה קרה, ו־eval בודק אם התוצאה טובה מספיק. העורך אינו מחליף בדיקות או גבול אמון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('visual-ai-builders-fundamentals',3,'יתרונות, חסרונות ומתי לבחור','יתרונות: גרף משותף לצוות, אבטיפוס מהיר והבנת מעבר הנתונים. חסרונות: runtime נוסף, גרסאות nodes, תלויות, רישוי וקושי בניידות. אם כל הדרישה היא REST call אחד עם לוגיקה עסקית בדוקה, קוד .NET רגיל עשוי להיות פשוט יותר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('visual-ai-builders-fundamentals',4,'פריסה ועלות כוללת','השוו עלות מודלים, אחסון, תורים, ניטור, רישיונות ותחזוקת שדרוגים. Self-host אינו מבטיח בידוד או היעדר עלויות; cloud אינו מבטיח שכל יכולת זמינה בכל מסלול. בדקו export, שחזור וניוד לוגיקה לפני תלות עמוקה במוצר.');
insert into academy.entry_sections (entry_id,position,title,body) values ('visual-ai-builders-fundamentals',5,'כלים היסטוריים וסיכון מחזור חיים','Flowise הוקפאה ב־29/07/2026, מאגרה אורכב ב־13/08 והיא הגיעה ל־EOL ב־31/08; אין המלצה להתחיל בה פיתוח חדש ואין מחליפה רשמית מאומתת. OpenAI Agent Builder הוכרז deprecated ב־03/06/2026 וסגירתו מתוכננת ל־30/11/2026; גם הוא אינו בחירה לפרויקט חדש. ChatKit נותר זמין. רשומות שני הכלים נשמרות בארכיון הקטלוג ואינן מוצגות ככלים פעילים.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('visual-ai-builders-fundamentals','must_learn','חובה להבין את גבולות המערכת, חוזי הנתונים וההרשאות לפני שמחברים מודל לכלים ולמידע ארגוני.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('visual-ai-builders-fundamentals','יסודות תכנון זרימות AI חזותיות, חוזי נתונים, הרשאות, בדיקות ובחירה בין פלטפורמה לקוד.','העקרונות מתאימים ל־C#/.NET, Python ו־TypeScript. שפת המימוש של העורך אינה שפת SDK; HTTP מאפשר אינטגרציה ואינו מבטיח שוויון יכולות.','not_applicable','פרק מושגים ללא מאגר מוצר מייצג.','2026-11-03');
