insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('langflow','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: שירות ASP.NET Core בודק זהות ומעביר שאלה ומזהי מסמכים מורשים ל־flow. רכיב retrieval מאחזר קטעים, רכיב מודל מנסח תשובה ורכיב Python מאמת answer ו־sourceIds. React מציג מקור ומסמן needsReview כשאין ראיה; אין לפרסם את העורך עצמו למשתמש הקצה.','בנו תכנון של שלושה רכיבים והוסיפו רכיב Python לבדיקת JSON. הגדירו מקרה מקור חסר וכשל מודל. השוו לאותה פעולה בשירות Python קטן שמופעל ב־HTTP מתוך .NET.','הרכיבים וההרחבות נכתבים ב־Python. API מאפשר צריכה מ־C#/.NET ומ־TypeScript; לא אומת SDK C# רשמי. TypeScript של ממשק העורך אינו הוכחה לתמיכה בכתיבת רכיבים באותה שפה.','Dify כשמעטפת היישום והידע חשובה יותר מהרחבת Python; LangGraph או LlamaIndex כשנדרשת שליטה בקוד ובבדיקות. Sim חלופה לזרימות אירועים וכלים, אך אינו אותו מודל רכיבים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langflow',0,'איזו בעיה הוא פותר?','גרף רכיבים מציג איך מידע עובר בין prompt, מודל, retrieval וכלים. זו פלטפורמה להרכבה ולהרצה, לא מודל שפה ולא LangGraph למרות הדמיון בשם. מומלץ להתחיל בגרף קטן שניתן להסביר ללא ממשק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langflow',1,'מימוש ושילוב במערכת','Custom components מגדירים קלטים ופלטים בקוד Python. אפליקציית .NET יכולה לצרוך flow דרך REST; העברת מפתח API אינה מגדירה הרשאות משתמש עסקיות. הפרידו את שירות ה־AI מה־API הארגוני והחזיקו חוזה פלט בדוק.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langflow',2,'יתרונות ומתי לבחור','יתרון פדגוגי: מעבר מוחשי מגרף לקוד רכיב, ונוחות להחלפת רכיבי RAG בלי לבנות מסך ניהול. מתאים לצוות שמוכן לתחזק Python ורוצה להשוות pipelines. רישיון הליבה MIT; רישיונות מודלים ושירותים נבדקים בנפרד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langflow',3,'חסרונות ומגבלות','העורך הוא IDE להרצת קוד. לפי תיעוד 1.13.x אין בידוד tenants בתוך process יחיד, ולכן שירות משותף דורש בידוד תשתיתי והגנת gateway חיצונית. חסימת custom components היא אמצעי נוסף ולא תחליף לבידוד. יש לתחזק גרסאות רכיבים ותלויות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('langflow',4,'השוואה לחלופות','Dify נותנת מעטפת יישום וידע רחבה; Langflow מתאימה כשנדרשת הרחבת רכיבי Python. שירות code-first מתאים כשהשליטה בקוד, debugging ובדיקות חשובה יותר מקנבס. בחירה אינה נגזרת מ־Stars. תאריך v1.0/cloud מ־24/06/2024 אינו ההשקה הראשונה, ולכן לא הוזן כתאריך ראשוני.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('langflow','should_know','כדאי להכיר כדי להבין גרפי רכיבים ולהרחיב שירות AI בקוד Python, תוך השוואה למימוש code-first.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('langflow','מרכיבה יישומי AI וגרפי RAG מרכיבי Python שניתן להרחיב ולהפעיל דרך HTTP.','הרכיבים וההרחבות נכתבים ב־Python. API מאפשר צריכה מ־C#/.NET ומ־TypeScript; לא אומת SDK C# רשמי. TypeScript של ממשק העורך אינו הוכחה לתמיכה בכתיבת רכיבים באותה שפה.','verified','מאגר הפרויקט הראשי בלבד; צילום מדידה מהמחקר המאושר.','2026-11-03');
