insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('microsoft-copilot-studio','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: עובד ב־Teams שואל על נוהל קליטת ציוד ומבקש פתיחת קריאה. הסוכן מאחזר ידע ארגוני, מבקש אישור וקורא ל־ASP.NET Core API. השרת מאמת את זהות העובד והרשאתו לפני כתיבה ל־SQL. לקוח .NET מותאם יכול לצרוך סוכן standard harness דרך ספריית ה־client הרשמית.','שרטטו maker, זהות סוכן ומשתמש קצה כשחקנים נפרדים. הגדירו הרשאת connector, תרחיש נתון חסוי וכשל שירות. בדקו איזו תכונה דורשת רישוי, ואיזה harness נתמך לפני בחירת client.','Microsoft 365 Agents SDK כולל client רשמי ודוגמאות ל־.NET, JavaScript ו־Python לצריכת סוכני Copilot Studio. התמיכה המתועדת כרגע היא ב־standard harness בלבד; GitHub Copilot harness אינו נתמך בו רשמית. זהו client ולא מימוש מנוע הפלטפורמה ב־C#.','Dify או Sim כשנדרשת פחות תלות ב־Power Platform; Microsoft Agent Framework או שירות ASP.NET בקוד לשליטה ב־runtime. Microsoft Foundry היא פלטפורמה נפרדת שכבר קיימת בקטלוג, לא שם חלופי למוצר הזה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-copilot-studio',0,'איזו בעיה הוא פותר?','הפלטפורמה מחברת יצירת סוכנים וזרימות למערכות וערוצי ארגון. היא מיועדת ל־makers ולמפתחים; מוצר SaaS זה נפרד מ־Microsoft Agent Framework ומ־Foundry. יש לבדוק כל יכולת לפי harness ומצב זמינות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-copilot-studio',1,'שילוב במערכת .NET','אפשר לצרוך סוכן דרך ספריית client ב־Microsoft 365 Agents SDK, עם מגבלת standard harness המתועדת. זהות משתמש ומדיניות connector נפרדות ממפתח שירות. העבירו פעולות SQL רגישות דרך API עסקי מאומת במקום לסמוך על ניסוח prompt.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-copilot-studio',2,'יתרונות ומתי לבחור','בחירה שימושית בסביבת Microsoft שמבקשת לחבר משתמשי Teams ונתונים ארגוניים ולהפעיל תהליכים תחת ממשל IT. הסביבה החזותית מאפשרת לצוות מוצר ו־IT להבין את השיחה והפעולות. יתרונות ההתאמה הם המלצה הנדסית, לא מדידת איכות.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-copilot-studio',3,'חסרונות ועלות','יש תלות בספק, ברישוי ובמגבלות harness. credits או תשלום לפי שימוש תלויים מסלול; trial אינו מבטיח אפשרות פרסום. Apps ויכולות authoring מסוימות מסומנות Preview, ואין להציגן כזמינות בכול מקום. העלות דורשת חישוב לתרחיש אמיתי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('microsoft-copilot-studio',4,'השוואה לחלופות','שירות ASP.NET או Microsoft Agent Framework מתאים לשליטה בקוד ובבדיקות; Dify מציעה מעטפת AI כללית במסלולי אירוח אחרים. Botpress מתמקדת יותר בחוויית שיחה וערוצים. אל תסיקו מתמיכת .NET ב־client שוויון לכל סוג סוכן.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('microsoft-copilot-studio','should_know','כדאי להכיר למפתח .NET שעובד עם זהויות ונתונים בארגון Microsoft; אין חובה לבחור בו מחוץ להקשר זה.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('microsoft-copilot-studio','בונה סוכנים וזרימות ארגוניות עם חיבור למערכות Microsoft, ערוצים ולקוחות יישום מותאמים.','Microsoft 365 Agents SDK כולל client רשמי ודוגמאות ל־.NET, JavaScript ו־Python לצריכת סוכני Copilot Studio. התמיכה המתועדת כרגע היא ב־standard harness בלבד; GitHub Copilot harness אינו נתמך בו רשמית. זהו client ולא מימוש מנוע הפלטפורמה ב־C#.','not_applicable','שירות Cloud ללא מאגר ליבה ציבורי מייצג; אין מדידה ממאגר SDK, v12 או כלי פיתוח.','2026-11-03');
