insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('sim','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: Webhook של בקשת תמיכה מפעיל workflow. סוכן מסווג בקשה, כלי קורא ASP.NET API במצב קריאה בלבד ומוצגת הצעת פעולה. לאחר אישור אדם, שרת .NET מאמת הרשאה ו־idempotency key לפני עדכון. React מציג סטטוס; גישת MCP מקבלת רק את ההרשאות הדרושות.','תכננו webhook, כלי HTTP ושער אישור. הוסיפו timeout ו־retry מוגבל ובדקו מה נשמר בלוג. השוו לאותה אוטומציה ב־n8n ולשירות TypeScript רגיל; חשבו גם אחסון ותורי רקע.','בתיעוד מופיעים SDK רשמיים ל־Python ול־TypeScript. .NET יכול לצרוך HTTP; SDK C# רשמי לא אומת. כתיבת קוד ב־Function תלויה בשפה וב־sandbox, ואינה הוכחה ל־runtime מקומי ל־.NET.','n8n לאוטומציה כללית של מערכות; Dify ליישום עם מעטפת ידע; Langflow לגרף רכיבי Python. FastGPT חלופה מוכוונת ידע שנדחתה בסבב הזה בשל חפיפה, לא בגלל פופולריות נמוכה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sim',0,'איזו בעיה הוא פותר?','Sim, שנקראה גם Sim Studio, מרכזת זרימות סוכנים עם כלים, טריגרים ומשאבי workspace. אפשר לחשוף workflow דרך API, צ׳אט או MCP. השם ההיסטורי אינו מוצר נוסף ואין לספור את שניהם בנפרד.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sim',1,'שילוב והפעלה','SDK Python/TypeScript ו־HTTP מאפשרים להפעיל workflow מתוך שרת יישום. מפתח אישי ומפתח workspace שונים בהיקף; OAuth הוא מסלול נפרד. שמרו credentials בשרת והגבילו כל כלי לפי הפעולה העסקית ולא לפי טקסט המודל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sim',2,'יתרונות ומתי לבחור','מתאימה להשוואת זרימות עם אירועים, כלים וקוד בסביבת TypeScript. נראות צעדים ולוגים יכולה לעזור להבין תקלה ולהפריד קריאת מודל מפעולה עסקית. יתרון זה תלוי תכנון; אין הבטחת latency או אמינות ללא בדיקה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sim',3,'חסרונות, רישוי ותפעול','Self-host כולל PostgreSQL, Redis, jobs ואחסון לפי התכונות. יש לגבות DB, קבצים ומפתחות; אובדן מפתח עלול למנוע גישה לנתונים מוצפנים. ליבת Apache2 נפרדת מ־Enterprise ברישיון מסחרי; הפעלת flags אינה הרשאה. שפות מסוימות דורשות sandbox חיצוני.');
insert into academy.entry_sections (entry_id,position,title,body) values ('sim',4,'השוואה לחלופות','בחרו Sim כש־API/MCP וזרימות אירועים הם מרכזיים; Dify כשמעטפת ידע ויישום חשובה יותר, ו־n8n לאוטומציה כללית. מספרי Stars של FastGPT ו־Sim דומים בצילום המחקר, ולכן ההבדל בהמלצה הוא תפקיד לימודי וחפיפה. יום השקה ראשונה לא אומת.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('sim','should_know','כדאי להכיר כהשוואה לזרימות סוכנים ואירועים עם TypeScript ו־API/MCP; אין צורך לתרגל בנוסף לכל כלי חזותי אחר.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('sim','מחברת סוכנים, כלים ואירועים לזרימות חזותיות הנחשפות דרך API, צ׳אט או שרת MCP.','בתיעוד מופיעים SDK רשמיים ל־Python ול־TypeScript. .NET יכול לצרוך HTTP; SDK C# רשמי לא אומת. כתיבת קוד ב־Function תלויה בשפה וב־sandbox, ואינה הוכחה ל־runtime מקומי ל־.NET.','verified','מאגר הפרויקט הראשי בלבד; צילום מדידה מהמחקר המאושר.','2026-11-03');
