insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('botpress','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: עוזר באתר React מבקש מזהה הזמנה, ואז מפנה את הלקוח לאימות בשרת .NET. רק לאחר האימות כלי מקבל סטטוס הזמנה דרך API מוגבל. בקשת ביטול דורשת אישור; כאשר חסר מידע או פעולה נכשלת, המערכת מעבירה לנציג עם תקציר ומזהה פנייה, בלי לחשוף פרטי לקוח אחר.','תכננו שיחה עם שלושה מצבים: בירור, אימות והסלמה. הגדירו איזה מידע מותר בלוג, איך מתבטל session ומה קורה ב־API timeout. השוו ל־Dify ול־Voiceflow בלי להניח שמצב שיחה הוא אימות משתמש.','Studio הוא עורך חזותי; ADK הוא מסלול TypeScript נפרד לבניית סוכנים בקוד. HTTP/Chat API מאפשר שילוב מ־C#/.NET; SDK C# רשמי לא אומת. אין הבטחת מעבר דו־כיווני מלא בין פרויקט ADK לגרף Studio.','Dify לזרימות AI וידע שאינן בעיקר שיחה; Voiceflow לעיצוב שיחות וקול בצוות מוצר; React עם backend בקוד כשנדרשים portability ושליטה רחבה. v12 אינה דרך התקנה חדשה של Botpress Cloud.');
insert into academy.entry_sections (entry_id,position,title,body) values ('botpress',0,'איזו בעיה הוא פותר?','Studio מחבר nodes ו־cards לזרימות שיחה עם ידע ומצב, ומאפשר לבנות שירות לקוחות או עוזר אתר. הוא פלטפורמת יישום מנוהלת, לא מודל. מומלץ לתכנן מראש חזרה לאדם ולא רק מסלול מוצלח של שיחה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('botpress',1,'שפות וממשקים','ADK ב־TypeScript הוא מסלול קוד מתועד; Cloud API מאפשר אינטגרציות HTTP עם שירותי .NET. שני מסלולים אלה אינם הבטחה ל־round-trip מול העורך החזותי. React מציג את החוויה, אך הרשאות לקוח ופעולות CRM או SQL נבדקות בשרת.');
insert into academy.entry_sections (entry_id,position,title,body) values ('botpress',2,'יתרונות ומתי לבחור','שימושי למוצר שהצורך המרכזי בו הוא שיחה, ערוצים, איסוף מידע והעברה לנציג. העורך מאפשר לצוות לתכנן מסלולי שירות בצורה משותפת; הרחבות קוד יכולות לשמש פעולות ייעודיות. אלה שיקולי בחירה, לא בדיקת איכות שיחה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('botpress',3,'חסרונות ועלות','יש תלות בשירות Cloud ובמסלול חיוב conversations ו־AI usage. v12 וגרסאות self-host מסומנות sunset ואינן מסלול חדש; הדבר אינו אומר שכל מנוי היסטורי נותק. MIT במאגר כלי הפיתוח אינו רישיון self-host לכל שירות הענן. ניידות מצב וגרפים דורשת בדיקה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('botpress',4,'השוואה לחלופות','Dify מתאימה למעטפת AI וידע כללית, Voiceflow עשויה להתאים לצוות עיצוב ול־voice, ושירות קוד מתאים לשליטה ב־runtime. אין מאגר ציבורי מייצג לשימוש ב־Botpress Cloud ולכן לא נמדדו Stars של SDK או devtools כאילו הם אימוץ השירות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('botpress','should_know','כדאי להכיר לתכנון שיחות וערוצים במוצר מעשי; משלים builder כללי בלי להפוך לחובה לכל מפתח AI.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('botpress','בונה סוכני שיחה וזרימות שירות עם ידע, ערוצים, מצב שיחה והעברה לנציג אנושי.','Studio הוא עורך חזותי; ADK הוא מסלול TypeScript נפרד לבניית סוכנים בקוד. HTTP/Chat API מאפשר שילוב מ־C#/.NET; SDK C# רשמי לא אומת. אין הבטחת מעבר דו־כיווני מלא בין פרויקט ADK לגרף Studio.','not_applicable','שירות Cloud ללא מאגר ליבה ציבורי מייצג; אין מדידה ממאגר SDK, v12 או כלי פיתוח.','2026-11-03');
