insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('flowise','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: במערכת Flowise קיימת, ממפים את הקלטים, הכלים והמצב לפני מעבר לשירות מתוחזק. יוצרים חוזה API ובדיקות השוואה, ואז משחזרים תרחיש מוגבל ב־Langflow או בקוד. אלה חלופות לבחינה, לא מחליפות רשמיות ולא converter מובטח.','כתבו תוכנית יציאה מכלי שהגיע ל־EOL: inventory, קיבוע גרסה, הגבלת גישה, ייצוא לוגיקה ובדיקות תוצאה. אל תפתחו פרויקט production חדש לצורך התרגיל.','תיעוד היסטורי מציג SDK Python/TypeScript ו־REST. זו אינה התחייבות לתמיכה נוכחית; SDK C# רשמי לא אומת. הימנעו מאימוץ חדש של runtime שאינו מתוחזק.','Langflow, Dify או שירות קוד מתוחזק הם חלופות לבחינה; אין מחליפה רשמית מאומתת ל־Flowise. תאימות flows או הגירה אוטומטית לא אומתו.');
insert into academy.entry_sections (entry_id,position,title,body) values ('flowise',0,'מחזור חיים והגבלת שימוש','הודעת הבעלים מציינת freeze ב־29/07/2026, archive ב־13/08/2026 ו־EOL ב־31/08/2026. דפי תיעוד ישנים אינם הבטחת תמיכה עתידית. הרשומה archived ואינה מוצגת ככלי פעיל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('flowise',1,'ערך ומגבלות היסטוריות','העורך המחיש הרכבה חזותית של מודלים וכלים. יתרון לימודי הוא הבנת הגרף; החיסרון כיום הוא אחריות עצמאית לתיקונים ולתלויות. Stars מצטברים אינם הוכחת תחזוקה.');
insert into academy.entry_sections (entry_id,position,title,body) values ('flowise',2,'השוואה לצורך מעבר','השוו פונקציות ותוצאות, לא רק צורת canvas. אין successor רשמי מאומת ולכן לא נקבע קישור lifecycle מחייב. התחילו במעטפת API ובדיקות לפני מעבר ל־Dify, Langflow או code-first.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('flowise','enrichment','העשרה היסטורית להבנת סיכון תחזוקה וניוד; אינה המלצת שימוש או תרגול ראשון.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('flowise','תיעוד היסטורי של Flowise לאחר EOL; ללא המלצה לפיתוח חדש או הצגה ככלי פעיל.','תיעוד היסטורי מציג SDK Python/TypeScript ו־REST. זו אינה התחייבות לתמיכה נוכחית; SDK C# רשמי לא אומת. הימנעו מאימוץ חדש של runtime שאינו מתוחזק.','not_applicable','תיעוד היסטורי מוסתר; אין שימוש במדדי מאגר כהמלצת שימוש פעילה.','2026-11-03');
