insert into academy.entry_lessons (entry_id,prerequisites,example,exercise,language_support_note,alternatives_note) values ('openai-agent-builder','HTTP/JSON, אימות משתמש ויסודות LLM; לכלי מעשי מומלץ להתחיל בפרק יסודות הבנייה החזותית.','דוגמה מעשית מוצעת שלא הורצה כאן: צוות עם workflow קיים מייצא קוד Python או TypeScript, משחזר כלי שירות דרך ASP.NET API ובודק control flow, הרשאות ותוצאות מול המקור. React יכול להשתמש בחוויית ChatKit עם backend מתאים; זו אפשרות תכנון שדורשת מימוש ובדיקות נפרדות.','מפו prompts, tools, triggers וגבולות הרשאה בזרימה קיימת. כתבו תוכנית מעבר ל־Agents SDK ובדיקות התנהגות. אל תניחו שהעברת הקוד ל־Workspace Agent שומרת כל התנהגות דטרמיניסטית.','מדריך המעבר מתאר יצוא Agents SDK code ב־Python או TypeScript. אין להסיק SDK C# לעורך; Agents SDK הקיים בקטלוג הוא פריט נפרד ו־ChatKit אינו ה־canvas המוצא משימוש.','המשך רשמי מתועד דרך Agents SDK או ChatGPT Workspace Agents בהתאם לתרחיש ולזמינות. ChatKit נותר זמין. Dify או Langflow הן חלופות עצמאיות לבחינה, לא מחליפות רשמיות או מסלולי יבוא אוטומטי.');
insert into academy.entry_sections (entry_id,position,title,body) values ('openai-agent-builder',0,'מחזור חיים והגבלת שימוש','ההוצאה משימוש הוכרזה ב־03/06/2026, והסגירה מתוכננת ל־30/11/2026. בזמן כתיבת הפרק משתמשים קיימים עדיין בחלון מעבר; אין לטעון שהסגירה כבר התבצעה. הרשומה archived ואינה מוצגת ככלי פעיל.');
insert into academy.entry_sections (entry_id,position,title,body) values ('openai-agent-builder',1,'יתרונות היסטוריים ומגבלות','הקנבס המחיש nodes וחוזי נתונים ואפשר preview ויצוא קוד. החיסרון המרכזי לפיתוח חדש הוא סגירה קרובה ותלות בשירות. ChatKit נשאר זמין; אין להכליל עליו את הודעת סיום ה־canvas.');
insert into academy.entry_sections (entry_id,position,title,body) values ('openai-agent-builder',2,'השוואה ונתיבי המשך','Agents SDK מתאים להמשך בקוד; Workspace Agents ליצירה ושיתוף לפי הרשאות וזמינות workspace. מעבר אינו המרה אוטומטית של graph ואינו מבטיח זהות התנהגות. יש לבדוק כלים, אימות ו־control flow לפני החלפת שירות.');
insert into academy.learning_guidance (entry_id,priority,reason,reviewed_at,basis) values ('openai-agent-builder','enrichment','העשרה היסטורית על תלות בפלטפורמה ומעבר לקוד; אינו מומלץ לבניית יישום חדש.','2026-11-03','editorial_learning');
insert into academy.catalog_facts (entry_id,description,language_support_summary,repository_status,repository_note,reviewed_at) values ('openai-agent-builder','תיעוד היסטורי של Agent Builder שהוצא משימוש, עם נתיבי יצוא והמשך שאינם הגירה אוטומטית.','מדריך המעבר מתאר יצוא Agents SDK code ב־Python או TypeScript. אין להסיק SDK C# לעורך; Agents SDK הקיים בקטלוג הוא פריט נפרד ו־ChatKit אינו ה־canvas המוצא משימוש.','not_applicable','תיעוד היסטורי מוסתר; אין שימוש במדדי מאגר כהמלצת שימוש פעילה.','2026-11-03');
