insert into academy.entry_sections (entry_id,position,title,body) values ('dify',5,'זרימות, Chatflow וסוכנים','יש להבחין Workflow למשימה עם צעדים מוגדרים, Chatflow לחוויית שיחה, ו־Agent לבחירת פעולות לפי הקשר. זמינות endpoints ותכונות נבדקת לפי סוג יישום וגרסה. אין צורך להחליף flow פשוט בסוכן מרובה כלים.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dify',6,'יתרונות ומתי לבחור כיום','Dify שימושית לבניית מעטפת יישום שמחברת ידע, מודלים ותהליך ונחשפת כ־API. היא מאפשרת לנסות תרחיש עסקי ולהשוות שינויי זרימה לפני כתיבת ממשק ניהול עצמאי. שיקול הבחירה הוא מהירות ניסוי ונראות, לא מספר Stars.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dify',7,'חסרונות, רישוי ותפעול','Self-host הוא stack של שירותי API, workers ותלויות ודורש שדרוג, גיבוי וניטור. הרישיון הנוכחי מבוסס Apache2 עם תנאים נוספים ל־multi-tenant ולמיתוג frontend; תיאור הרישוי בפוסט2023 היסטורי בלבד. עלות כוללת גם ספק מודל ואחסון.');
insert into academy.entry_sections (entry_id,position,title,body) values ('dify',8,'השוואה ובחירה מול חלופות','Langflow מתאימה להרחבת רכיבי Python; Sim לזרימות אירועים וכלים; Copilot Studio לסביבת Microsoft ו־Botpress למוצר שיחתי. כשנדרשת בעיקר לוגיקה עסקית בדוקה, השאירו אותה בשירות .NET קטן. Flowise עברה EOL ואינה חלופה פעילה חדשה.');
