insert into academy.category_guides (category_id,title,introduction,note) values ('06','מ־canvas למערכת AI שניתן לתחזק','התחילו ביסודות ובכלי מעשי אחד. לאחר מכן השוו מסלול Python, סביבת Microsoft, זרימות אירועים או חוויית שיחה לפי הצורך; אין חובה ללמוד את כל הפלטפורמות לעומק.','הסדר הוא המלצה פדגוגית, לא דירוג תפוצה. התרגילים מוצעים ולא הורצו במחקר. Flowise ו־OpenAI Agent Builder מתועדים כהיסטוריים בפרק היסודות ובארכיון, ללא המלצת אימוץ חדש.');
