-- Approved visual06-20261103-v1 V06-01–V06-07 plus explicit historical-record request.
-- Content only. Archived historical records are excluded by the existing published-only loader.
begin isolation level serializable;
select pg_advisory_xact_lock(hashtext('academy-migrations'));
do $$ begin
 if (select max(version) from academy.schema_migrations) is distinct from 9 then raise exception 'Expected schema version 9'; end if;
 if (select count(*) from academy.entries)<>57 or (select count(*) from academy.entry_categories where category_id='06')<>1 then raise exception 'Catalog changed since review'; end if;
 if (select document from academy.entry_documents where slug='dify') is distinct from '{"id":"dify","kind":"platform","name":"Dify","slug":"dify","addedAt":"2026-10-31","example":"תרחיש לימודי: אבטיפוס לשאלות על נוהל קליטת עובד. המערכת מחזירה תשובה עם מקור ומפנה לאדם כאשר המידע אינו מספיק.","sources":[{"url":"https://docs.dify.ai/en/home","title":"Dify — Documentation","supports":"יישומי AI, סוכנים, ידע, תהליכים ופרסום דרך Web/API. תכנון האבטיפוס והשיקולים הם שלנו.","checkedAt":"2026-10-31"}],"summary":"פלטפורמה לבניית יישומי AI, תהליכים וצ''אטבוטים עם חיבור לנתונים ולממשקי API.","exercise":"צייר ארבעה שלבים לצ''אטבוט נוהלים. תוצר: חוזה לכל מעבר, מקרה ללא מקור ושתי בדיקות למידע שאסור לחשוף. הסבר מה יישאר בקוד הארגוני.","revision":2,"sections":[{"text":"Dify מציעה סביבת בנייה ליישומי AI, סוכנים ותהליכים. התיעוד מציג חיבור לידע ופרסום כיישום Web או אינטגרציה דרך API. זהו מוצר סביב היישום, ולא מודל בפני עצמו.","title":"מה היא פותרת?"},{"text":"המלצה: הפרד קלט משתמש, שליפת ידע, קריאת מודל ועיבוד פלט. הגדר במפורש נתונים שעוברים בין השלבים, ומצב שבו אין מקור או שהמודל מחזיר תשובה לא תקינה.","title":"איך מתכננים זרימה?"},{"text":"אפשר לחשוב על הפלטפורמה כשכבת יישום שניתן לחבר למסך דרך API. עדיין צריך לתכנן אימות משתמשים, שמירת מצב והגבול שבין הדפדפן לשרת.","title":"החיבור ל־React ו־REST"},{"text":"המלצה: אבטיפוס ושיתוף תהליך AI עם אנשים שרוצים להבין אותו חזותית. כשיש כללים עסקיים מורכבים, שקול לחשוף שירות קטן שמממש אותם בקוד בדוק.","title":"מתי לבחור?"},{"text":"בדוק הרשאות לידע, ספקי מודלים ומסלול האירוח. בהשוואה כלול גם עלות מודל ותחזוקת הפלטפורמה. אל תחשוף מפתח שרת של היישום בקוד React.","title":"אבטחה ועלות"}],"verifiedAt":"2026-10-31","categoryIds":["06"],"addedAtBasis":"historical_backfill","relatedSlugs":["n8n","llamaindex","mcp"],"revisionNote":"פרק לימוד. האימות מתייחס להגדרת המוצר וליכולות המתוארות במקורות; מחירים, גרסאות חבילות וביצועים לא נבדקו. שיקולי התכנון והתרגילים הם תוכן לימודי שלנו.","prerequisites":"מודל שפה, HTTP והגדרת תהליך.","alternativesNote":"Flowise ו־Langflow הם מועמדים ממפת הידע להשוואה. חלופה בקוד יכולה להיות React עם שירות AI ממוקד, כשנדרשת שליטה גבוהה יותר.","learningPriority":"should_know","publicationStatus":"published","verificationStatus":"verified","languageSupportNote":"בנייה חזותית אינה SDK ל־C#, Python או TypeScript. שילוב API יכול לשרת כל לקוח HTTP; שוויון יכולות בין מסלולי אירוח לא נבדק כאן."}'::jsonb then raise exception 'Reviewed Dify document changed'; end if;
 if exists(select 1 from academy.entries where id in ('visual-ai-builders-fundamentals','langflow','microsoft-copilot-studio','sim','botpress','flowise','openai-agent-builder') or slug in ('visual-ai-builders-fundamentals','langflow','microsoft-copilot-studio','sim','botpress','flowise','openai-agent-builder') or lower(name) in ('בניית ai חזותית — יסודות ובחירת כלי','langflow','microsoft copilot studio','sim','botpress','flowise — היסטורי','openai agent builder — היסטורי')) then raise exception 'Visual candidate already exists'; end if;
 if exists(select 1 from academy.repositories where url in ('https://github.com/langflow-ai/langflow','https://github.com/simstudioai/sim','https://github.com/FlowiseAI/Flowise')) then raise exception 'Candidate repository already represented'; end if;
 if exists(select 1 from academy.entry_releases where entry_id='dify') or exists(select 1 from academy.category_guides where category_id='06') then raise exception 'Reviewed facts or guide changed'; end if;
end $$;
update academy.entries set revision=revision+1,verified_at='2026-11-03',revision_note='V06-02 מאושר: הרחבת דוגמה, יתרונות, חסרונות וחלופות, רישוי ופריסה; מקורות וסעיפים קודמים נשמרו. הדוגמאות לא הורצו.' where slug='dify';
update academy.entry_lessons set example='דוגמה מעשית מוצעת שלא הורצה כאן: React שולח שאלה ל־ASP.NET Core המאמת משתמש ובוחר מזהי ידע מורשים. Dify Workflow שולף קטעי נוהל, מפעיל מודל ומחזיר answer, sourceIds ו־needsReview. אם המשתמש מבקש פתיחת קריאה, מוצג אישור ורק API עסקי ב־.NET מבצע כתיבה עם בדיקת הרשאות ו־idempotency key; מפתח Dify אינו בדפדפן.',exercise='תכננו Workflow לשאלת נוהל ופעולת פתיחת קריאה נפרדת. הגדירו חוזה JSON, מקור חסר, timeout והרשאה חסרה. השוו ל־Langflow ולמימוש ASP.NET קטן, וחשבו עלות מודל, אחסון ותחזוקת self-host.',language_support_note='ליבת backend ב־Python וממשק Web ב־React/Next.js; אלה שפות מימוש ולא הוכחת SDK. Code node תומך Python/JavaScript לפי התיעוד. C#/.NET יכול לצרוך REST מצד השרת; SDK .NET רשמי ושוויון יכולות בין מסלולי אירוח לא אומתו.',alternatives_note='Langflow להרחבת רכיבי Python; Sim לתזמור כלים ואירועים עם API/MCP; Copilot Studio לסביבת Microsoft ו־Botpress לשיחות וערוצים. Flowise היא חלופה היסטורית בלבד לאחר EOL ב־31/08/2026 ואינה המלצה לפרויקט חדש. שירות ASP.NET ממוקד עשוי להספיק ללוגיקה פשוטה.' where entry_id='dify';
update academy.catalog_facts set language_support_summary='ליבת backend ב־Python וממשק Web ב־React/Next.js; אלה שפות מימוש ולא הוכחת SDK. Code node תומך Python/JavaScript לפי התיעוד. C#/.NET יכול לצרוך REST מצד השרת; SDK .NET רשמי ושוויון יכולות בין מסלולי אירוח לא אומתו.',reviewed_at='2026-11-03' where entry_id='dify';
delete from academy.entry_language_labels where entry_id='dify';
do $$ begin
 if (select count(*) from academy.entries where slug in ('visual-ai-builders-fundamentals','langflow','microsoft-copilot-studio','sim','botpress','flowise','openai-agent-builder'))<>7 then raise exception 'Incomplete visual additions'; end if;
 if (select count(*) from academy.entry_categories c join academy.entries e on e.id=c.entry_id where c.category_id='06' and e.publication_status='published')<>6 then raise exception 'Expected six published visual entries'; end if;
 if (select count(*) from academy.entries where slug in ('flowise','openai-agent-builder') and publication_status='archived')<>2 then raise exception 'Historical records must remain archived'; end if;
 if (select revision from academy.entries where slug='dify')<>3 then raise exception 'Dify revision missing'; end if;
end $$;
commit;
